create extension if not exists pgcrypto;
create type public.workspace_role as enum ('owner','admin','editor','viewer');
create type public.brand_analysis_status as enum ('not_started','pending','completed','failed');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, created_at timestamptz not null default now());
create table public.workspaces(id uuid primary key default gen_random_uuid(), name text not null check(char_length(name) between 1 and 120), slug text unique, created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.workspace_members(workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.workspace_role not null default 'editor', created_at timestamptz not null default now(), primary key(workspace_id,user_id));
create table public.brands(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null, description text, logo_path text, colors jsonb not null default '{\"primary\":[],\"secondary\":[],\"neutrals\":[]}'::jsonb, typography jsonb not null default '{\"heading\":null,\"body\":null}'::jsonb, visual_style jsonb not null default '[]'::jsonb, rules jsonb not null default '{\"do\":[],\"dont\":[]}'::jsonb, analysis_status public.brand_analysis_status not null default 'not_started', approved_at timestamptz, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.brand_assets(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, brand_id uuid not null references public.brands(id) on delete cascade, storage_path text not null unique, original_filename text not null, mime_type text not null, file_size_bytes bigint not null check(file_size_bytes between 1 and 15728640), asset_kind text not null check(asset_kind in ('guideline','logo','reference','font','other')), metadata jsonb not null default '{}'::jsonb, uploaded_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.templates(id uuid primary key default gen_random_uuid(), name text not null, description text, category text not null, width integer not null default 1080, height integer not null default 1080, preview_path text, canvas_schema jsonb not null default '{}'::jsonb, is_public boolean not null default true, created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, brand_id uuid not null references public.brands(id), template_id uuid references public.templates(id) on delete set null, title text not null default 'Sans titre', width integer not null default 1080, height integer not null default 1080, canvas_json jsonb not null default '{}'::jsonb, thumbnail_path text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.generations(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, brand_id uuid references public.brands(id) on delete set null, project_id uuid references public.projects(id) on delete set null, status text not null default 'queued' check(status in ('queued','processing','completed','failed')), input_summary text, output jsonb, provider text, model text, estimated_cost_usd numeric(12,6), created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), completed_at timestamptz);
create table public.plans(id text primary key, name text not null, monthly_price_xof integer not null default 0, monthly_generation_limit integer not null default 10, monthly_export_limit integer not null default 20, max_brands integer not null default 1);
create table public.subscriptions(id uuid primary key default gen_random_uuid(), workspace_id uuid not null unique references public.workspaces(id) on delete cascade, plan_id text not null references public.plans(id), status text not null default 'trialing' check(status in ('trialing','active','past_due','cancelled','expired')), provider text, provider_customer_id text, provider_subscription_id text, current_period_start timestamptz, current_period_end timestamptz, created_at timestamptz not null default now());
create table public.usage_events(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid references auth.users(id) on delete set null, event_type text not null check(event_type in ('brand_analysis','design_generation','png_export','asset_upload')), quantity integer not null default 1 check(quantity>0), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index brands_workspace_idx on public.brands(workspace_id); create index brand_assets_brand_idx on public.brand_assets(brand_id); create index projects_workspace_updated_idx on public.projects(workspace_id,updated_at desc); create index usage_workspace_created_idx on public.usage_events(workspace_id,created_at desc);
create function public.is_workspace_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.workspace_members m where m.workspace_id=target and m.user_id=(select auth.uid())); $$;
create function public.has_workspace_role(target uuid, roles public.workspace_role[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.workspace_members m where m.workspace_id=target and m.user_id=(select auth.uid()) and m.role=any(roles)); $$;
revoke all on function public.is_workspace_member(uuid) from public; revoke all on function public.has_workspace_role(uuid,public.workspace_role[]) from public; grant execute on function public.is_workspace_member(uuid) to authenticated; grant execute on function public.has_workspace_role(uuid,public.workspace_role[]) to authenticated;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.workspaces enable row level security; alter table public.workspace_members enable row level security; alter table public.brands enable row level security; alter table public.brand_assets enable row level security; alter table public.templates enable row level security; alter table public.projects enable row level security; alter table public.generations enable row level security; alter table public.plans enable row level security; alter table public.subscriptions enable row level security; alter table public.usage_events enable row level security;
create policy "read own profile" on public.profiles for select to authenticated using(id=(select auth.uid())); create policy "update own profile" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy "members read workspaces" on public.workspaces for select to authenticated using(public.is_workspace_member(id)); create policy "create workspace" on public.workspaces for insert to authenticated with check(created_by=(select auth.uid())); create policy "admins update workspace" on public.workspaces for update to authenticated using(public.has_workspace_role(id,array['owner','admin']::public.workspace_role[])) with check(public.has_workspace_role(id,array['owner','admin']::public.workspace_role[])); create policy "owners delete workspace" on public.workspaces for delete to authenticated using(public.has_workspace_role(id,array['owner']::public.workspace_role[]));
create policy "members read memberships" on public.workspace_members for select to authenticated using(public.is_workspace_member(workspace_id)); create policy "admins manage memberships" on public.workspace_members for all to authenticated using(public.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[])) with check(public.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[]));
create policy "members read brands" on public.brands for select to authenticated using(public.is_workspace_member(workspace_id)); create policy "editors create brands" on public.brands for insert to authenticated with check(public.has_workspace_role(workspace_id,array['owner','admin','editor']::public.workspace_role[]) and created_by=(select auth.uid())); create policy "editors update brands" on public.brands for update to authenticated using(public.has_workspace_role(workspace_id,array['owner','admin','editor']::public.workspace_role[])) with check(public.has_workspace_role(workspace_id,array['owner','admin','editor']::public.workspace_role[])); create policy "admins delete brands" on public.brands for delete to authenticated using(public.has_workspace_role(workspace_id,array['owner','admin']::public.workspace_role[]));
create policy "members read assets" on public.brand_assets for select to authenticated using(public.is_workspace_member(workspace_id)); create policy "editors add assets" on public.brand_assets for insert to authenticated with check(public.has_workspace_role(workspace_id,array['owner','admin','editor']::public.workspace_role[]) and uploaded_by=(select auth.uid())); create policy "editors delete assets" on public.brand_assets for delete to authenticated using(public.has_workspace_role(workspace_id,array['owner','admin','editor']::public.workspace_role[]));
create policy "read public templates" on public.templates for select to authenticated using(is_public=true); create policy "members read projects" on public.projects for select to authenticated using(public.is_workspace_member(workspace_id)); create policy "editors create projects" on public.projects for insert to authenticated with check(public.has_workspace_role(workspace_id,array['owner','admin','editor']::public.workspace_role[]) and created_by=(select auth.uid())); create policy "editors update projects" on public.projects for update to authenticated using(public.has_workspace_role(workspace_id,array['owner','admin','editor']::public.workspace_role[])) with check(public.has_workspace_role(workspace_id,array['owner','admin','editor']::public.workspace_role[])); create policy "editors delete projects" on public.projects for delete to authenticated using(public.has_workspace_role(workspace_id,array['owner','admin','editor']::public.workspace_role[]));
create policy "members read generations" on public.generations for select to authenticated using(public.is_workspace_member(workspace_id)); create policy "members read subscriptions" on public.subscriptions for select to authenticated using(public.is_workspace_member(workspace_id)); create policy "read plans" on public.plans for select to authenticated using(true); create policy "members read usage" on public.usage_events for select to authenticated using(public.is_workspace_member(workspace_id));
insert into public.plans(id,name,monthly_price_xof,monthly_generation_limit,monthly_export_limit,max_brands) values('free','Découverte',0,10,20,1),('starter','Starter',3000,50,100,1),('business','Business',7500,200,500,5) on conflict(id) do nothing;

-- Automatically make the workspace creator its first owner.
create function public.add_workspace_creator_as_owner()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  insert into public.workspace_members(workspace_id,user_id,role)
  values(new.id,new.created_by,'owner')
  on conflict(workspace_id,user_id) do nothing;
  return new;
end;
$$;
create trigger workspace_creator_membership
after insert on public.workspaces
for each row execute procedure public.add_workspace_creator_as_owner();
